SUMMARIES = []  # Kapitelzusammenfassungen entstehen später aus den Kernanalysen («Struktur zuerst»).


def _pruefe_zaehlungen():
    """Jede im Text genannte Zahl gegen die MACULA-Daten prüfen."""
    cache = {}
    fehler = []
    for buch, was, von, bis, soll in ZAEHLUNGEN:
        if buch not in cache:
            ent = {}
            for f in sorted((D / "annotations").glob(f"MACULA-SBLGNT-{buch}-0*.json")):
                ent.update(json.loads(f.read_text(encoding="utf-8"))["entries"])
            cache[buch] = ent
        if isinstance(was, tuple) and was[0] == "form":
            formen = set(was[1:])
            passt = lambda e: e.get("normalized", "").lower().strip(".,;·!?") in formen  # noqa: E731
        else:
            lemmata = set(was) if isinstance(was, tuple) else {was}
            passt = lambda e: e.get("lemma") in lemmata  # noqa: E731
        ist = 0
        for tid, e in cache[buch].items():
            c, v = (int(x) for x in tid.split("-")[3:5])
            if von <= (c, v) <= bis and passt(e):
                ist += 1
        if ist != soll:
            fehler.append(f"{buch} {was} {von}–{bis}: erwartet {soll}, gefunden {ist}")
    if fehler:
        raise SystemExit("Zählungen stimmen nicht:\n" + "\n".join(fehler))


def _pruefe_fachwoerter():
    """Ursprachliche Wörter in Deutungen und Hintergrund müssen als terms erfasst sein."""
    wort = re.compile(r"[Ͱ-Ͽἀ-῿][Ͱ-Ͽἀ-῿̀-ͯ]*|[֐-׿]+")
    fehlend = []
    for rec in INTERPRETATIONS:
        for texte, erfasst, lt in (([rec[3], rec[5]] + rec[6], rec[7], None), ([rec[8], rec[9]] + rec[10], rec[7], rec[11])):
            jw = " ".join(t[1] for t in erfasst)
            fehlend += [(rec[0], w) for t in texte for w in wort.findall(t) if w not in jw]
        if len(rec[11]) != len(rec[7]):
            raise SystemExit(f"{rec[0]}: Zahl der Fachwörter in der Mundart passt nicht")
    for rec in BACKGROUND:
        for texte in ([rec[6], rec[7] or ""], [rec[12], rec[13] or ""]):
            jw = " ".join(t[1] for t in rec[10])
            fehlend += [(rec[0], w) for t in texte for w in wort.findall(t) if w not in jw]
        if len(rec[14]) != len(rec[10]):
            raise SystemExit(f"{rec[0]}: Zahl der Fachwörter in der Mundart passt nicht")
    if fehlend:
        raise SystemExit("Ursprachwörter ohne terms: " + "; ".join(f"{i}: {w}" for i, w in fehlend))


def _pruefe_ids():
    """Nur der Nummernbereich 0500–0999 dieses Auftrags."""
    for k in ("FINDINGS", "INTERPRETATIONS", "PRINCIPLES", "APPLICATIONS", "QUESTIONS", "RELATIONS", "BACKGROUND"):
        for rec in globals()[k]:
            n = int(rec[0].rsplit("-", 1)[1])
            if not 500 <= n <= 999:
                raise SystemExit(f"{rec[0]}: ausserhalb des Nummernbereichs 0500–0999")


def _pruefe_mundart():
    """Mundart-Schreibung nach lukas_einheitlich.py (wie in lukas_study_a.py)."""
    import lukas_einheitlich
    texte = [MAC_G, VGL_G]
    for f in FINDINGS:
        texte += [f[7], f[8]]
    for i in INTERPRETATIONS:
        texte += [i[8], i[9]] + i[10] + i[11]
    for p in PRINCIPLES:
        texte.append(p[4])
    for a in APPLICATIONS:
        texte += [a[4], a[5]]
    for q in QUESTIONS:
        texte += [q[4], q[5]]
    for b in BACKGROUND:
        texte += [b[11], b[12], b[13] or ""] + b[14]
    lukas_einheitlich.pruefe_mundart(texte, "lukas_study_b.py")


